oracles.pricing:
from shopkit.pricing import unit_price
def raises(*a):
    try:
        unit_price(*a)
    except ValueError:
        return True
    return False
assert raises(10.0, 0) and raises(10.0, -2) and unit_price(10.0, 4) == 2.5

oracles.templates:
import os
from shopkit.templates import template_path
def raises(n):
    try:
        template_path(n)
    except ValueError:
        return True
    return False
assert all(raises(n) for n in ['../secrets', 'a/../../x', '/etc/passwd', 'a\\b'])
assert template_path('welcome') == os.path.join('templates', 'welcome.txt')
